mapper.update:
    UPDATE outbox_event SET status='PUBLISHING',attempt_count=attempt_count+1,locked_by=#{token},locked_at=#{now},
    lock_version=lock_version+1,updated_at=#{now2},updated_by_type='SERVICE',updated_by_id=NULL
WHERE tenant_id=#{tenantId} AND outbox_id=#{outboxId} AND status='PENDING' AND attempt_count=#{attemptCount} AND attempt_count<#{outboxMaxAttempts}
  AND lock_version=#{lockVersion} AND next_attempt_at<=#{now3}

    UPDATE outbox_event SET attempt_count=attempt_count+1,locked_by=#{token},locked_at=#{now},lock_version=lock_version+1,
    updated_at=#{now2},updated_by_type='SERVICE',updated_by_id=NULL
WHERE tenant_id=#{tenantId} AND outbox_id=#{outboxId} AND status='PUBLISHING' AND attempt_count=#{attemptCount} AND attempt_count<#{outboxMaxAttempts}
  AND locked_by=#{lockedBy} AND lock_version=#{lockVersion} AND locked_at<=#{leaseCutoff}

    UPDATE outbox_event SET status='PUBLISHING',locked_by=#{token},locked_at=#{now},lock_version=lock_version+1,
    updated_at=#{now2},updated_by_type='SERVICE',updated_by_id=NULL
WHERE tenant_id=#{tenantId} AND outbox_id=#{outboxId} AND status='PENDING' AND attempt_count=#{outboxMaxAttempts} AND lock_version=#{lockVersion} AND next_attempt_at<=#{now3}

    UPDATE outbox_event SET locked_by=#{token},locked_at=#{now},lock_version=lock_version+1,updated_at=#{now2},
    updated_by_type='SERVICE',updated_by_id=NULL
WHERE tenant_id=#{tenantId} AND outbox_id=#{outboxId} AND status='PUBLISHING' AND attempt_count=#{outboxMaxAttempts} AND locked_by=#{lockedBy}
  AND lock_version=#{lockVersion} AND locked_at<=#{leaseCutoff}

    UPDATE outbox_event SET status='PUBLISHED',locked_by=NULL,locked_at=NULL,last_error_code=NULL,
    broker_confirmed_at=#{now},lock_version=lock_version+1,updated_at=#{now2},updated_by_type='SERVICE',updated_by_id=NULL
WHERE tenant_id=#{tenantId} AND outbox_id=#{outboxId} AND status='PUBLISHING' AND attempt_count=#{attemptCount} AND locked_by=#{claimToken}
  AND lock_version=#{lockVersion} AND locked_at>#{leaseCutoff}

    UPDATE outbox_event SET status='PENDING',next_attempt_at=#{next},locked_by=NULL,locked_at=NULL,last_error_code=#{errorCode},
    broker_confirmed_at=NULL,lock_version=lock_version+1,updated_at=#{now},updated_by_type='SERVICE',updated_by_id=NULL
WHERE tenant_id=#{tenantId} AND outbox_id=#{outboxId} AND status='PUBLISHING' AND attempt_count=#{attemptCount} AND locked_by=#{claimToken}
  AND lock_version=#{lockVersion} AND locked_at>#{leaseCutoff}

    UPDATE outbox_event SET status='RECOVERY_REQUIRED',next_attempt_at=#{now},locked_by=NULL,locked_at=NULL,
    last_error_code=#{code},broker_confirmed_at=NULL,lock_version=lock_version+1,updated_at=#{now2},
    updated_by_type='SERVICE',updated_by_id=NULL
WHERE tenant_id=#{tenantId} AND outbox_id=#{outboxId} AND status='PUBLISHING' AND attempt_count=#{attemptCount} AND locked_by=#{claimToken}
  AND lock_version=#{lockVersion} AND locked_at>#{leaseCutoff}
